#   POST /api/bookings
#   POST /api/businesses
#   etc.
#
# We will gradually replace these with Supabase-backed routes.
# ============================================================

@app.post("/api/{kind}")
async def upsert(
    kind: str,
    req: Request,
):
    """Save one legacy shared record.

    Sending the same ID again replaces it only when the incoming
    record is at least as recent as the stored record.
    """

    if kind not in KINDS:
        raise HTTPException(
            status_code=404,
            detail="Unknown kind.",
        )

    raw = await req.body()

    if len(raw) > MAX_BYTES:
        raise HTTPException(
            status_code=413,
            detail="Record is too large.",
        )

    try:
        rec = json.loads(
            raw
        )

    except json.JSONDecodeError:
        raise HTTPException(
            status_code=400,
            detail="Body must be JSON.",
        )

    if (
        not isinstance(
            rec,
            dict,
        )
        or not isinstance(
            rec.get("id"),
            str,
        )
        or not 0 < len(
            rec["id"]
        ) <= 80
    ):
        raise HTTPException(
            status_code=400,
            detail="Record needs a short text id.",
        )

    missing = [
        field
        for field
        in REQUIRED[kind]
        if rec.get(field) in (
            None,
            "",
        )
    ]

    if missing:
        raise HTTPException(
            status_code=400,
            detail=(
                "Missing: "
                + ", ".join(
                    missing
                )
            ),
        )

    with _lock:
        store = load()

        bucket = store.setdefault(
            kind,
            {},
        )

        old = bucket.get(
            rec["id"]
        )

        if (
            old
            and (
                old.get("ts")
                or 0
            )
            > (
                rec.get("ts")
                or 0
            )
        ):
            return {
                "ok": True,
                "kept": "newer copy already stored",
            }

        bucket[
            rec["id"]
        ] = rec

        save(
            store
        )

    return {
        "ok": True,
    }


